mapper.select:
SELECT B.FINPROD_ID finprodId, B.FINPROD_TYPE finprodType, B.FINPROD_TYPE finprodTypeCode, B.PRIN prin, B.CCY ccy, B.CCY ccyCode, DATE_FORMAT(B.VDATE,'%Y-%m-%d') as vdate, DATE_FORMAT(B.MDATE,'%Y-%m-%d') as mdate, B.TERM term, B.TERM_TYPE termType, B.TERM_TYPE termTypeCode, B.INT_TYPE intType, B.INT_RATE*100 intRate, B.INT_RATE_ID intRateId, B.BASIS basis, B.M_PRIN_AMT mPrinAmt, B.M_INT_AMT mIntAmt, B.M_TRADE_AMT mTradeAmt, C.TYPE_2 type2, C.TYPE_2 type2Code, B.CAPI_INCOME_FEATURE capiIncomeFeature, B.CAPI_INCOME_FEATURE capiIncomeFeatureCode, B.CALENDAR_ID calendarId, D.CALENDAR_NAME calendarName FROM FIN_TRADE_PRODUCT B LEFT JOIN FIN_PRODUCT_TYPE C ON C.FINPROD_ID = B.FINPROD_ID LEFT JOIN MST_CALENDAR_INFO D ON D.CALENDAR_ID = B.CALENDAR_ID WHERE (B.BRANCH = 0 OR B.BRANCH IS NULL) AND B.FINPROD_ID =#{finprodId} AND B.FINPROD_TYPE =#{finprodType}
union all
SELECT B.FINPROD_ID finprodId, B.FINPROD_TYPE finprodType, B.FINPROD_TYPE finprodTypeCode, null prin, B.CCY ccy, B.CCY ccyCode, DATE_FORMAT(B.VDATE,'%Y-%m-%d') as vdate, DATE_FORMAT(B.MDATE,'%Y-%m-%d') as mdate, B.Mdate - B.Vdate term, null termType, null termTypeCode, null intType, null intRate, null intRateId, vccr.basis basis, null mPrinAmt, null mIntAmt, null mTradeAmt, C.TYPE_2 type2, C.TYPE_2 type2Code, B.CAPI_INCOME_FEATURE capiIncomeFeature, B.CAPI_INCOME_FEATURE capiIncomeFeatureCode, B.CALENDAR_ID calendarId, D.CALENDAR_NAME calendarName FROM fin_product B LEFT JOIN FIN_PRODUCT_TYPE C ON C.FINPROD_ID = B.FINPROD_ID LEFT JOIN MST_CALENDAR_INFO D ON D.CALENDAR_ID = B.CALENDAR_ID
left join (select vccr.* from fin_CASH_CALC_RULE vccr where vccr.eff_date = (select max(cash_rule.eff_date) from fin_CASH_CALC_RULE cash_rule where cash_rule.finprod_id = vccr.finprod_id and cash_rule.finprod_type = vccr.finprod_type)) vccr on B.finprod_id = vccr.finprod_id and B.finprod_type = vccr.finprod_type
WHERE B.FINPROD_ID = #{finprodId} AND B.FINPROD_TYPE = #{finprodType}
